) AS v(id, category_id, question_text, correct_answer, incorrect_answers,
       difficulty, level_number, language, image_url)
ON CONFLICT (id) DO UPDATE SET
  question_text     = EXCLUDED.question_text,
  correct_answer    = EXCLUDED.correct_answer,
  incorrect_answers = EXCLUDED.incorrect_answers,
  difficulty        = EXCLUDED.difficulty,
  level_number      = EXCLUDED.level_number,
  image_url         = EXCLUDED.image_url,
  is_active         = true,
  in_production     = true,
  updated_at        = now();

-- total_levels is derived, not typed in. The trigger on questions recomputes it
-- on every insert, so this is a belt-and-braces recount written as the same
-- expression the trigger uses — LEAST(38, thinnest language / 10) — in case the
-- rows are loaded in a session where the trigger is disabled.
UPDATE public.categories c
SET total_levels = COALESCE((
      SELECT LEAST(38, GREATEST(1, FLOOR(MIN(per_language)::decimal / 10)::integer))
      FROM (
        SELECT COUNT(*) AS per_language
        FROM public.questions q
        WHERE q.category_id = c.id
          AND q.is_active = true
          AND q.in_production = true
        GROUP BY q.language
      ) counts
    ), 1),
    levels_updated_at = now()
WHERE c.category_id = 'guess_city';
